import time
t=time.time()
N,S,K=153,155,4
dp=[[0]*(S+1) for _ in range(K+1)]
dp[0][0]=1
for x in range(1,N+1):
    for k in range(K,0,-1):
        for s in range(S,x-1,-1):
            dp[k][s]+=dp[k-1][s-x]
# brute check
c=0
for a in range(1,N+1):
    for b in range(a+1,N+1):
        if a+b>S: break
        for cc in range(b+1,N+1):
            d=S-a-b-cc
            if d<=cc: break
            if d<=N: c+=1
print(dp[K][S],c,time.time()-t)

