import time
from sympy import factorint
from sympy.ntheory.modular import crt
t=time.time()
x0=429877406843; m=860310645368; n=226970731486097
f=factorint(m); mods=[];res=[]
for p,k in f.items():
    q=p**k
    if x0%p==0:
        r=0 if n>=10 else pow(x0,2**n,q)  # 2^n>=k -> 0
    else:
        ph=q//p*(p-1)
        r=pow(x0%q,pow(2,n,ph),q)
    mods.append(q);res.append(r)
ans=int(crt(mods,res)[0])
def direct(N):
    x=x0
    for _ in range(N): x=x*x%m
    return x
def fast(N):
    rr=[]
    for p,k in f.items():
        q=p**k
        if x0%p==0: rr.append(pow(x0,2**N,q) if N<10 else 0)
        else: rr.append(pow(x0%q,pow(2,N,q//p*(p-1)),q))
    return int(crt(mods,rr)[0])
assert all(direct(N)==fast(N) for N in range(60))
print(f,ans,time.time()-t)
